update public.destinations d set province=f.province,category=f.category,location=public.st_setsrid(public.st_makepoint(f.longitude,f.latitude),4326),status='Activo',source_url=f.source_url,source_checked_at=now()
from fixes f where d.id=f.id returning d.id,d.status)
select count(*) updated_count,count(*) filter(where status='Activo') active_count from updated;

